            int no_cost = edge_cost_applies ? abs(j - initial_prefix) : 0;
            int select_cost = edge_cost_applies ? abs((j + 1) - initial_prefix) : 0;

            for (int s = 0; s <= 9 * j; s++) {
                int cost = dp[j][s];
                if (cost == INF) {
                    continue;
                }

                if (j < K) {
                    int ns = s + P[i];
                    int nc = cost + select_cost;
                    if (nc < dp[j + 1][ns]) {
