static int dp2[MAXN + 1][MAXR + 1];

int main(void) {
    int N, K;
    long long T;

    if (scanf("%d %d %lld", &N, &K, &T) != 3) return 0;

    int P[MAXN + 1], G[MAXN + 1], start[MAXN + 1];
    for (int i = 1; i <= N; i++) scanf("%d", &P[i]);
    int count = 0;
    for (int i = 1; i <= N; i++) {
        scanf("%d", &G[i]);
        if (G[i]) start[++count] = i;
    }

    int (*prev)[MAXR + 1] = dp1;
    int (*next)[MAXR + 1] = dp2;

    for (int j = 1; j <= K; j++) {
        int upper = N - K + j;
        int maxPrevReward = 9 * (j - 1);
        int maxReward = 9 * j;
        int prefix[MAXR + 1];

        for (int r = 0; r <= maxPrevReward; r++) prefix[r] = INF;
        if (j == 1) prefix[0] = 0;

        for (int x = j; x <= upper; x++) {
            if (j > 1) {
                int *row = prev[x - 1];
                for (int r = 0; r <= maxPrevReward; r++) {
                    if (row[r] < prefix[r]) prefix[r] = row[r];
                }
            }

            for (int r = 0; r <= maxReward; r++) next[x][r] = INF;

            int move = x - start[j];
            if (move < 0) move = -move;

            for (int r = 0; r <= maxPrevReward; r++) {
                if (prefix[r] != INF) {
                    int reward = r + P[x];
                    next[x][reward] = prefix[r] + move;
                }
            }
        }

        int (*tmp)[MAXR + 1] = prev;
        prev = next;
        next = tmp;
    }

    int answer = 0;
    for (int reward = 0; reward <= 9 * K; reward++) {
        int bestCost = INF;
        for (int x = K; x <= N; x++) {
            if (prev[x][reward] < bestCost) bestCost = prev[x][reward];
        }
        if ((long long)bestCost <= T) answer = reward;
    }

    printf("%d\n", answer);
    return 0;
}
